import { isValidObjectId } from "mongoose";
import { Driver } from "../../Models/driver.model.js";

export const addDriver = async (req, res) => {
  try {
    const { name, mobile_no, age, licence_no, experience, status } = req.body;

    if (!name) {
      return res.status(404).json({
        message: "Enter Name",
        success: false
      })
    } else if (!mobile_no) {
      return res.status(404).json({
        message: "Enter Mobile No.",
        success: false
      })
    } else if (!age) {
      return res.status(404).json({
        message: "Enter Age ",
        success: false
      })
    } else if (!licence_no) {
      return res.status(404).json({
        message: "Enter Licence No.",
        success: false
      })
    } else if (!experience) {
      return res.status(404).json({
        message: "Enter Experience.",
        success: false
      })
    } else if (!status) {
      return res.status(404).json({
        message: "Select Status.",
        success: false
      })
    }
    const driverData = {
      name, mobile_no, age, licence_no, experience, status
    }

    const response = await Driver(driverData);
    await response.save();
    return res.status(200).json({
      messaage: "Driver added Successfully",
      success: true,
      data: response
    })

  } catch (error) {
    console.log(error);
    return res.status(404).json({
      message: "Error While Adding Driver.",
      success: false,
      error: error.messaage
    })
  }
}

export const editDriver = async (req, res) => {
  try {
    const { id } = req.params;
    if (!isValidObjectId(id)) {
      return res.status(404).json({
        messaage: "Invalid Id",
        success: false
      })
    }
    const operation = await Driver.findById(id);
    if (!operation) {
      return res.status(404).json({
        messaage: "Data not exist in database",
        success: false
      })
    }
    const data = {
      name: req.body.name,
      mobile_no: req.body.mobile_no,
      age: req.body.age,
      licence_no: req.body.licence_no,
      experience: req.body.experience
    }
    const response = await Driver.findByIdAndUpdate(id, data, { new: true });
    return res.status(200).json({
      messaage: "Driver Updated Successfully",
      success: true
    })
  } catch (error) {
    console.log(error);
    return res.status(404).json({
      messaage: "Error while Updating Driver",
      success: false
    })
  }
}

export const deleteDriver = async (req, res) => {
  try {
    const { id } = req.params;
    if (!isValidObjectId(id)) {
      return res.status(404).json({
        messaage: "Invalid Id",
        success: false
      })
    }
    const operation = await Driver.findById(id);
    if (!operation) {
      return res.status(404).json({
        messaage: "Data not exist in DB",
        success: false
      })
    }
    const response = await Driver.findByIdAndDelete(id);
    return res.status(200).json({
      messaage: "Driver Deleted Successfully",
      success: true
    })
  } catch (error) {
    console.log(error);
    return res.status(404).json({
      messaage: "Error while Deleting Driver",
      success: false
    })
  }
}

export const viewDriver = async (req, res) => {
  try {
    const { id } = req.params;
    if (!isValidObjectId(id)) {
      return res.status(404).json({
        messaage: "Invalid Id",
        success: false
      })
    }
    const operation = await Driver.findById(id);
    if (!operation) {
      return res.status(404).json({
        messaage: "Data not exist in DB",
        success: false
      })
    }
    return res.status(200).json({
      messaage: "Data fetched Successfully",
      success: true,
      data: operation
    })
  } catch (error) {
    console.log(error)
    return res.status(404).json({
      messaage: "Error while viewing driver",
      success: false
    })
  }
}